#include "rom/sysroms.h"
#include "rom/sha1.h"

#include <stdio.h>
#include <string.h>

// Generated by cmake/embed.cmake from external/open-roms/
extern const unsigned char bb_openroms_kernal[];
extern const unsigned long bb_openroms_kernal_size;
extern const unsigned char bb_openroms_basic[];
extern const unsigned long bb_openroms_basic_size;
extern const unsigned char bb_openroms_chargen[];
extern const unsigned long bb_openroms_chargen_size;

const char* sysroms_source_name(sysroms_source_t src) {
    return src == SYSROMS_SOURCE_USER ? "user-supplied" : "Open ROMs";
}

void sysroms_load_default(sysroms_t* roms) {
    memset(roms, 0, sizeof(*roms));
    memcpy(roms->kernal, bb_openroms_kernal, sizeof(roms->kernal));
    memcpy(roms->basic, bb_openroms_basic, sizeof(roms->basic));
    memcpy(roms->chargen, bb_openroms_chargen, sizeof(roms->chargen));
    roms->kernal_basic_source = SYSROMS_SOURCE_OPENROMS;
    roms->chargen_source = SYSROMS_SOURCE_OPENROMS;
    sha1_hex(roms->kernal, sizeof(roms->kernal), roms->kernal_sha1);
    sha1_hex(roms->basic, sizeof(roms->basic), roms->basic_sha1);
    sha1_hex(roms->chargen, sizeof(roms->chargen), roms->chargen_sha1);
}

typedef enum { RD_MISSING, RD_OK, RD_BAD_SIZE } read_result_t;

// Reads exactly `size` bytes; the file must be exactly that size.
static read_result_t read_exact(const char* dir, const char* name, uint8_t* dst, size_t size) {
    char path[1024];
    snprintf(path, sizeof(path), "%s/%s", dir, name);
    FILE* f = fopen(path, "rb");
    if (!f) {
        return RD_MISSING;
    }
    size_t n = fread(dst, 1, size, f);
    int extra = fgetc(f);
    fclose(f);
    return (n == size && extra == EOF) ? RD_OK : RD_BAD_SIZE;
}

// 1541 ROMs verified with real dumps (SHA-1 of the whole 16 KB, $C000-$FFFF).
static const struct { const char* sha1; const char* name; } known_1541[] = {
    { "e15e0742a9b42492916050fbe95f1e22b0b01932", "1541 CBM DOS V2.6 (World dump)" },
    { "f88ca9c3c9d1d383f4d348db54095c77f8597a11", "1541 CBM DOS V2.6 (Japan/USA dump)" },
};

const char* sysroms_1541_name(const char* sha1) {
    for (size_t i = 0; i < sizeof(known_1541) / sizeof(known_1541[0]); i++) {
        if (!strcmp(sha1, known_1541[i].sha1)) return known_1541[i].name;
    }
    return NULL;
}

// 1541.rom, or 1541-c000.rom + 1541-e000.rom. False (with a message) when the
// files are present but unusable.
static bool load_1541(sysroms_t* roms, const char* dir, char* err, size_t err_size) {
    static uint8_t rom[0x4000];
    const read_result_t r = read_exact(dir, "1541.rom", rom, sizeof(rom));
    const read_result_t rc = read_exact(dir, "1541-c000.rom", rom, 0x2000);
    const read_result_t re = read_exact(dir, "1541-e000.rom", rom + 0x2000, 0x2000);
    if (r == RD_OK) {
        read_exact(dir, "1541.rom", rom, sizeof(rom));      // the halves may have overwritten it
    } else if (r == RD_BAD_SIZE || rc == RD_BAD_SIZE || re == RD_BAD_SIZE) {
        if (err) snprintf(err, err_size, "1541 ROM in %s has the wrong size (1541.rom 16384, 1541-c000.rom/1541-e000.rom 8192 bytes)", dir);
        return false;
    } else if (rc != re) {
        if (err) snprintf(err, err_size, "1541-c000.rom and 1541-e000.rom must be supplied together (found only %s in %s)",
                          rc == RD_OK ? "1541-c000.rom" : "1541-e000.rom", dir);
        return false;
    } else if (rc == RD_MISSING) {
        return true;    // no drive ROM: fine
    }
    memcpy(roms->drive1541, rom, sizeof(rom));
    roms->has_1541 = true;
    sha1_hex(roms->drive1541, sizeof(roms->drive1541), roms->drive1541_sha1);
    roms->drive1541_name = sysroms_1541_name(roms->drive1541_sha1);
    return true;
}

bool sysroms_load(sysroms_t* roms, const char* dir, char* err, size_t err_size) {
    sysroms_load_default(roms);
    if (err && err_size) err[0] = 0;
    if (!dir || !dir[0]) {
        return true;
    }
    static uint8_t kernal[0x2000], basic[0x2000], chargen[0x1000];
    read_result_t rk = read_exact(dir, "kernal.rom", kernal, sizeof(kernal));
    read_result_t rb = read_exact(dir, "basic.rom", basic, sizeof(basic));
    read_result_t rc = read_exact(dir, "chargen.rom", chargen, sizeof(chargen));

    bool ok = true;
    if (rk == RD_BAD_SIZE || rb == RD_BAD_SIZE || rc == RD_BAD_SIZE) {
        if (err) snprintf(err, err_size, "system ROM in %s has the wrong size (kernal/basic 8192, chargen 4096 bytes)", dir);
        return false;
    }
    if ((rk == RD_OK) != (rb == RD_OK)) {
        if (err) snprintf(err, err_size, "kernal.rom and basic.rom must be supplied together (found only %s in %s)",
                          rk == RD_OK ? "kernal.rom" : "basic.rom", dir);
        ok = false;     // still honour a valid chargen override below
    }
    else if (rk == RD_OK) {
        memcpy(roms->kernal, kernal, sizeof(kernal));
        memcpy(roms->basic, basic, sizeof(basic));
        roms->kernal_basic_source = SYSROMS_SOURCE_USER;
        sha1_hex(roms->kernal, sizeof(roms->kernal), roms->kernal_sha1);
        sha1_hex(roms->basic, sizeof(roms->basic), roms->basic_sha1);
    }
    if (rc == RD_OK) {
        memcpy(roms->chargen, chargen, sizeof(chargen));
        roms->chargen_source = SYSROMS_SOURCE_USER;
        sha1_hex(roms->chargen, sizeof(roms->chargen), roms->chargen_sha1);
    }
    if (!load_1541(roms, dir, ok ? err : NULL, err_size)) ok = false;
    return ok;
}
